package android.util;public class Base64{public static final int NO_WRAP=2;public static byte[] decode(String s,int flags){return ((flags&8)!=0?java.util.Base64.getUrlDecoder():java.util.Base64.getDecoder()).decode(s);}public static String encodeToString(byte[] bytes,int flags){return java.util.Base64.getEncoder().encodeToString(bytes);}}
